<script setup>import {reactive} from 'vue';import {router} from '@inertiajs/vue3';import Layout from './Layout.vue';defineProps({products:Array});const form=reactive({name:'',description:'',price:'',image:'',is_active:true});function create(){router.post('/admin/products',form,{onSuccess:()=>Object.assign(form,{name:'',description:'',price:'',image:'',is_active:true})})}function toggle(p){router.patch('/admin/products/'+p.id,{name:p.name,description:p.description,price:p.price,image:p.image,is_active:!p.is_active},{preserveScroll:true});}</script>
<template><Layout><p class="eyebrow">Catalog</p><h1 class="serif text-5xl font-bold">Products</h1><div class="card mt-6"><h2 class="serif text-2xl font-bold">Add flavor</h2><div class="mt-4 grid gap-3 md:grid-cols-2"><input v-model="form.name" class="field" placeholder="Flavor name"><input v-model="form.price" class="field" placeholder="Optional price"><textarea v-model="form.description" class="field md:col-span-2" placeholder="Description"></textarea><input v-model="form.image" class="field md:col-span-2" placeholder="Image URL (optional)"></div><button @click="create" class="pill dark mt-4">Add product</button></div><div class="mt-5 grid gap-3"><article v-for="p in products" :key="p.id" class="card flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h2 class="serif text-2xl font-bold">{{p.name}}</h2><p class="text-sm opacity-60">{{p.description}}</p></div><div class="flex items-center gap-3"><span class="font-bold">{{p.price || '—'}} EGP</span><button @click="toggle(p)" class="pill">{{p.is_active?'Active':'Hidden'}}</button></div></article></div></Layout></template>
